// Method: TextServer::draw_hex_code_box
static JSValue js_TextServer_draw_hex_code_box(JSContext* ctx, JSValueConst this_val, int argc, JSValueConst* argv) {
    if (argc < 1) {
        return JS_ThrowTypeError(ctx, "TextServer.draw_hex_code_box: missing handle argument");
    }

    int64_t handle;
    if (JS_ToInt64(ctx, &handle, argv[0]) < 0) {
        return JS_ThrowTypeError(ctx, "TextServer.draw_hex_code_box: invalid handle");
    }

    QuickJSContext* qjs_ctx = get_qjs_ctx(ctx);
    if (!qjs_ctx || !qjs_ctx->get_object_registry()) {
        return JS_ThrowInternalError(ctx, "Context not initialized");
    }

    // Check WRITE rate limit (PRD Section 6.4)
    ExecutionLimiter* limiter = qjs_ctx->get_execution_limiter();
    if (limiter && !limiter->check_api_rate_limit(ApiCategory::WRITE)) {
        return JS_ThrowInternalError(ctx, "TextServer.draw_hex_code_box: write rate limit exceeded");
    }

    Object* obj = qjs_ctx->get_object_registry()->get_object(handle);
    if (!obj) {
        return JS_ThrowTypeError(ctx, "TextServer.draw_hex_code_box: invalid or freed object");
    }

    TextServer* typed_obj = Object::cast_to<TextServer>(obj);
    if (!typed_obj) {
        return JS_ThrowTypeError(ctx, "TextServer.draw_hex_code_box: object is not a TextServer");
    }

    // Argument count check (excluding handle) - only required args
    if (argc < 6) {
        return JS_ThrowTypeError(ctx, "TextServer.draw_hex_code_box: expected at least 5 arguments, got %d", argc - 1);
    }

    // Convert arguments
    RID arg_canvas = qjs_ctx->js_to_variant(argv[1]);
    int64_t arg_size; JS_ToInt64(ctx, &arg_size, argv[2]);
    double tmp_x_pos, tmp_y_pos;
    JSValue jx_pos = JS_GetPropertyStr(ctx, argv[3], "x");
    JSValue jy_pos = JS_GetPropertyStr(ctx, argv[3], "y");
    JS_ToFloat64(ctx, &tmp_x_pos, jx_pos);
    JS_ToFloat64(ctx, &tmp_y_pos, jy_pos);
    JS_FreeValue(ctx, jx_pos);
    JS_FreeValue(ctx, jy_pos);
    Vector2 arg_pos(tmp_x_pos, tmp_y_pos);
    int64_t arg_index; JS_ToInt64(ctx, &arg_index, argv[4]);
    double tmp_r_color, tmp_g_color, tmp_b_color, tmp_a_color = 1.0;
    JSValue jr_color = JS_GetPropertyStr(ctx, argv[5], "r");
    JSValue jg_color = JS_GetPropertyStr(ctx, argv[5], "g");
    JSValue jb_color = JS_GetPropertyStr(ctx, argv[5], "b");
    JSValue ja_color = JS_GetPropertyStr(ctx, argv[5], "a");
    JS_ToFloat64(ctx, &tmp_r_color, jr_color);
    JS_ToFloat64(ctx, &tmp_g_color, jg_color);
    JS_ToFloat64(ctx, &tmp_b_color, jb_color);
    if (!JS_IsUndefined(ja_color)) JS_ToFloat64(ctx, &tmp_a_color, ja_color);
    JS_FreeValue(ctx, jr_color);
    JS_FreeValue(ctx, jg_color);
    JS_FreeValue(ctx, jb_color);
    JS_FreeValue(ctx, ja_color);
    Color arg_color(tmp_r_color, tmp_g_color, tmp_b_color, tmp_a_color);

    typed_obj->draw_hex_code_box(arg_canvas, arg_size, arg_pos, arg_index, arg_color);
    return JS_UNDEFINED;
}

